import{_ as a,o as e,c as n,a3 as s}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"多租户","description":"","frontmatter":{},"headers":[],"relativePath":"guide/multi-tenancy.md","filePath":"guide/multi-tenancy.md","lastUpdated":1790242299000}'),i={name:"guide/multi-tenancy.md"};function d(l,t,o,r,c,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h1><p>框架提供租户上下文、租户解析中间件与数据隔离基础设施。本章讲隔离策略怎么选、上下文怎么切、写路径为什么和读路径不一样。</p><p>完整 API 见 <a href="./../packages/multitenancy">MultiTenancy</a> 与 <a href="./../packages/multitenancy-abstractions">MultiTenancy.Abstractions</a>。</p><h2 id="两种隔离策略" tabindex="-1">两种隔离策略 <a class="header-anchor" href="#两种隔离策略" aria-label="Permalink to &quot;两种隔离策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适用</th></tr></thead><tbody><tr><td><strong>字段级隔离</strong></td><td>所有租户共库共表，靠 <code>Tenant_Id</code> 列 + 全局查询过滤器区分</td><td><strong>默认</strong>。租户多、单租户数据量不大</td></tr><tr><td>库级隔离</td><td>每个租户独立连接串</td><td>单租户数据量大、合规要求物理隔离</td></tr></tbody></table><p>两种可以混用——同一套代码里，一部分租户走共享库、一部分走独立库，由租户的连接配置决定。</p><h2 id="租户上下文" tabindex="-1">租户上下文 <a class="header-anchor" href="#租户上下文" aria-label="Permalink to &quot;租户上下文&quot;">​</a></h2><p><code>ICurrentTenant</code> 是运行期的租户身份：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OrderService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ICurrentTenant</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> currentTenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ITransientDependency</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">? </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TenantId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> currentTenant.Id;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// null 与 0 同义：平台（0 号租户）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="谁来设置它" tabindex="-1">谁来设置它 <a class="header-anchor" href="#谁来设置它" aria-label="Permalink to &quot;谁来设置它&quot;">​</a></h3><p>请求链路里由 <strong><code>XiHanTenantResolveMiddleware</code></strong> 设置，位置在<strong>认证之后</strong>（要读令牌里的租户 claim）、<strong>授权之前</strong>（授权判定要在租户上下文里进行）。</p><p>非请求场景（定时任务、后台作业、控制台）<strong>没有中间件</strong>，要自己切：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (currentTenant.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Change</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tenantId))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 这个块里所有仓储查询都带上该租户的过滤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>框架的任务调度与后台作业已经内建了这一步——执行时按「参数 tenantId → 任务归属租户 → 当前异步上下文」的优先级解析并切换。</p><h3 id="平台就是-0-号租户" tabindex="-1">平台就是 0 号租户 <a class="header-anchor" href="#平台就是-0-号租户" aria-label="Permalink to &quot;平台就是 0 号租户&quot;">​</a></h3><p>没有租户上下文（<code>Id == null</code>）与 <code>Change(0)</code> 同义，都是<strong>平台</strong>，也就是 0 号租户。平台和任何一个租户一样，只看、只写自己的数据：</p><ul><li>读：平台只看 <code>TenantId = 0</code> 的行，<strong>看不到任何租户的数据</strong>；</li><li>写：新行落 <code>TenantId = 0</code>；预置了别的租户标识的插入直接拒绝；只能改写 / 删除 <code>TenantId = 0</code> 的行。</li></ul><p>不存在「没有租户上下文就看全部、写全部」的隐式口径。跨租户只有显式通道：</p><table tabindex="0"><thead><tr><th>需求</th><th>做法</th></tr></thead><tbody><tr><td>跨租户读取（按全局唯一邮箱定位账号、按会话标识找会话等）</td><td>仓储里 <code>CreateNoTenantQueryable()</code>，或在查询上 <code>.ClearTenantFilter()</code>（读共享与严格隔离的过滤一并清除）</td></tr><tr><td>写某个租户的数据（开通租户、逐租户维护）</td><td><code>using (currentTenant.Change(tenantId))</code> 切入该租户后再写</td></tr><tr><td>用户自有行（账号、会话、个人设置）</td><td><code>TenantWriteGuard.Suppress()</code>，见 <a href="./data">数据访问</a></td></tr></tbody></table><p><code>IsAvailable</code> 表示「当前处于某个业务租户」，平台（<code>null</code> 或 <code>0</code>）为 <code>false</code>。</p><div class="warning custom-block"><p class="custom-block-title">不要直接写 <code>ClearFilter&lt;IMultiTenantEntity&gt;()</code></p><p>租户过滤按读共享（<code>IMultiTenantEntity</code>）与严格隔离（<code>IStrictMultiTenantEntity</code>）两个类型登记，只清前者时严格隔离实体仍被收紧在当前作用域，跨租户读取会静默缺数据。统一用 <code>ClearTenantFilter()</code> / <code>ClearTenantAndSoftDeleteFilter()</code>。</p></div><h2 id="全局记录约定" tabindex="-1">全局记录约定 <a class="header-anchor" href="#全局记录约定" aria-label="Permalink to &quot;全局记录约定&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title"><code>TenantId = 0</code> 而不是 NULL</p><p>框架与 BasicApp 的约定是用 <strong><code>TenantId = 0</code></strong> 表示平台级/全局记录，<strong>不用 NULL</strong>。业务租户 Id 从 1 开始。</p><p>好处：列非空、索引干净、<code>WHERE TenantId IN (0, @current)</code> 这类合并查询写起来自然。</p><p>需要 <code>IsGlobal</code> 语义时用<strong>派生只读属性</strong> <code>IsGlobal =&gt; TenantId == 0</code>，<strong>不落库</strong>——避免两个字段漂移。</p></div><h2 id="读写口径不对称" tabindex="-1">读写口径不对称 <a class="header-anchor" href="#读写口径不对称" aria-label="Permalink to &quot;读写口径不对称&quot;">​</a></h2><p>这是多租户里最容易出事的一点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读：全局过滤器放行 TenantId IN (0, 当前租户)    ← 租户能读到平台全局数据；平台只读 0</span></span>
<span class="line"><span>写：只能改写 / 删除当前作用域的行              ← 租户不能改 0 号全局行，平台也不能改租户行</span></span></code></pre></div><p>平台与租户各自独有、不存在共用的数据（运行数据、日志、会话等），实体再实现 <code>IStrictMultiTenantEntity</code> 收紧为严格相等：租户态只看本租户行，不再读共享平台行。</p><div class="danger custom-block"><p class="custom-block-title">「读共享」不等于「写共享」</p><p>如果写路径复用读的口径，租户就能改掉平台的全局数据——这是越权。</p><p>框架的做法：预读守卫校验取回行的 <code>TenantId</code>，条件写自动追加当前作用域的 <code>Where</code>。要维护全局数据，在平台（0 号租户）作用域里改。</p></div><h2 id="实体怎么支持多租户" tabindex="-1">实体怎么支持多租户 <a class="header-anchor" href="#实体怎么支持多租户" aria-label="Permalink to &quot;实体怎么支持多租户&quot;">​</a></h2><p>继承 <code>SugarMultiTenant*</code> 系列基类即可——它们带 <code>Tenant_Id</code> 列并实现 <code>IMultiTenantEntity</code>。</p><div class="danger custom-block"><p class="custom-block-title">只加列不实现接口 = 隔离完全失效</p><p>全局过滤器是按 <code>AddTableFilter&lt;IMultiTenantEntity&gt;</code> 挂的。实体只加了 <code>TenantId</code> 列却没实现 <code>IMultiTenantEntity</code>，过滤器对它<strong>全程 no-op</strong>——所有租户都能看到所有数据，且没有任何报错。</p><p>用框架提供的 <code>SugarMultiTenant*</code> 基类就不会踩到；手写实体时务必确认接口实现上了。</p></div><h2 id="切换租户" tabindex="-1">切换租户 <a class="header-anchor" href="#切换租户" aria-label="Permalink to &quot;切换租户&quot;">​</a></h2><p>用户从一个租户切到另一个时，正确做法是<strong>复用会话、轮换令牌</strong>：</p><ul><li>不发登录事件、不新增设备记录；</li><li>在目标租户上下文里重建授权快照（不同租户可用功能不同）。</li></ul><p>如果实现成「登出再登录」，用户会收到两条登录通知、设备列表里多出一台设备。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>查到了别的租户数据</td><td>实体没实现 <code>IMultiTenantEntity</code>（只加了列）</td></tr><tr><td>后台任务里查不到租户数据</td><td>后台没有租户上下文即平台，只看得到平台数据；逐个 <code>Change(tenantId)</code> 切入租户处理</td></tr><tr><td>改不了全局数据</td><td>这是<strong>有意的</strong>——在平台（0 号租户）作用域里改</td></tr><tr><td>切租户后权限没变</td><td>授权快照没在目标上下文重建</td></tr><tr><td>平台下查不到租户数据</td><td>这是<strong>有意的</strong>——平台只看自己的数据；确需跨租户读取用 <code>ClearTenantFilter()</code> / <code>CreateNoTenantQueryable()</code></td></tr><tr><td>平台插入报「平台上下文只能写入平台数据」</td><td>在平台里给行预置了租户标识；写某个租户的数据要先切入该租户</td></tr><tr><td>跨租户读取漏了一部分表</td><td>只清了 <code>IMultiTenantEntity</code> 过滤，严格隔离实体仍被收紧；改用 <code>ClearTenantFilter()</code></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./data">数据访问</a>：全局查询过滤器</li><li><a href="./authentication">认证与授权</a>：租户解析在管道里的位置</li><li><a href="./../packages/multitenancy">MultiTenancy 包</a>：完整 API</li></ul>`,39)])])}const u=a(i,[["render",d]]);export{k as __pageData,u as default};
